import type { Config } from "../config.js";
import type { Agent, Deployment, Principal } from "../domain/schemas.js";
import { runtimeKey } from "../storage/tenant-store.js";

/** Trusted template, never generated by an LLM or supplied by a browser. */
export function agentTemplate(
  c: Config,
  p: Principal,
  agent: Agent,
  d: Deployment,
) {
  const account = c.KRONO_CLUSTER_ARN.split(":")[4],
    partition = "aws",
    pk = runtimeKey(p, agent.id);
  if (!/^\d{12}$/.test(account)) throw Error("Invalid cluster account");
  const table = (name: string) =>
    `arn:${partition}:dynamodb:${c.AWS_REGION}:${account}:table/${name}`;
  const prefix = `tenants/${p.userId}/agents/${agent.id}/`;
  const policy = {
    Version: "2012-10-17",
    Statement: [
      {
        Effect: "Allow",
        Action: ["dynamodb:GetItem", "dynamodb:ConditionCheckItem"],
        Resource: table(c.KRONO_AGENT_CONTROL_TABLE),
        Condition: {
          "ForAllValues:StringEquals": {
            "dynamodb:LeadingKeys": [pk, `TENANT#${p.userId}#POLICY`],
          },
          Null: { "dynamodb:LeadingKeys": "false" },
        },
      },
      {
        Effect: "Allow",
        Action: [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:Query",
          "dynamodb:ConditionCheckItem",
        ],
        Resource: table(c.KRONO_RUNTIME_TABLE),
        Condition: {
          "ForAllValues:StringEquals": { "dynamodb:LeadingKeys": [pk] },
          Null: { "dynamodb:LeadingKeys": "false" },
        },
      },
      {
        Effect: "Allow",
        Action: ["s3:GetObject", "s3:PutObject", "s3:AbortMultipartUpload"],
        Resource: `arn:aws:s3:::${c.KRONO_ARTIFACT_BUCKET}/${prefix}*`,
      },
      {
        Effect: "Allow",
        Action: ["kms:Decrypt", "kms:GenerateDataKey"],
        Resource: c.KRONO_RUNTIME_KMS_ARN,
        Condition: {
          StringEquals: {
            "kms:ViaService": [
              `s3.${c.AWS_REGION}.amazonaws.com`,
              `sqs.${c.AWS_REGION}.amazonaws.com`,
            ],
          },
        },
      },
      {
        Effect: "Allow",
        Action: ["sqs:SendMessage"],
        Resource: [c.KRONO_COORDINATION_QUEUE_URL, c.KRONO_ANALYSIS_QUEUE_URL]
          .filter(Boolean)
          .map(
            (url) =>
              `arn:aws:sqs:${c.AWS_REGION}:${account}:${url!.split("/").at(-1)}`,
          ),
      },
    ],
  };
  const env: Record<string, string> = {
    AWS_REGION: c.AWS_REGION,
    KRONO_TENANT_ID: p.userId,
    KRONO_AGENT_ID: agent.id,
    KRONO_DEPLOYMENT_ID: d.id,
    KRONO_RUNTIME_TABLE: c.KRONO_RUNTIME_TABLE,
    KRONO_AGENT_CONTROL_TABLE: c.KRONO_AGENT_CONTROL_TABLE,
    KRONO_ARTIFACT_BUCKET: c.KRONO_ARTIFACT_BUCKET,
    KRONO_CHECKPOINT_PREFIX: prefix,
    KRONO_COORDINATION_QUEUE_URL: c.KRONO_COORDINATION_QUEUE_URL,
    ...(c.KRONO_ANALYSIS_QUEUE_URL
      ? { KRONO_ANALYSIS_QUEUE_URL: c.KRONO_ANALYSIS_QUEUE_URL }
      : {}),
    TERMINAL_MODE: "SIMULATION",
    RESEARCH_ENABLED: "false",
    LANGSMITH_TRACING: "false",
    LANGCHAIN_TRACING_V2: "false",
    PYTHONUNBUFFERED: "1",
  };
  return {
    AWSTemplateFormatVersion: "2010-09-09",
    Description: "KRONO approved isolated Python agent",
    Resources: {
      TaskRole: {
        Type: "AWS::IAM::Role",
        Properties: {
          RoleName: `krono-${c.KRONO_ENV}-agent-${agent.id.slice(0, 20)}-${agent.deploymentVersion}-task`,
          PermissionsBoundary: c.KRONO_AGENT_BOUNDARY_ARN,
          AssumeRolePolicyDocument: {
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Principal: { Service: "ecs-tasks.amazonaws.com" },
                Action: "sts:AssumeRole",
                Condition: {
                  StringEquals: { "aws:SourceAccount": account },
                  ArnLike: {
                    "aws:SourceArn": `arn:aws:ecs:${c.AWS_REGION}:${account}:*`,
                  },
                },
              },
            ],
          },
          Policies: [{ PolicyName: "ScopedAgent", PolicyDocument: policy }],
        },
      },
      Task: {
        Type: "AWS::ECS::TaskDefinition",
        Properties: {
          Family: d.stackName,
          Cpu: String(agent.specification.execution.cpu),
          Memory: String(agent.specification.execution.memoryMiB),
          NetworkMode: "awsvpc",
          RequiresCompatibilities: ["FARGATE"],
          ExecutionRoleArn: c.KRONO_TASK_EXECUTION_ROLE_ARN,
          TaskRoleArn: { "Fn::GetAtt": ["TaskRole", "Arn"] },
          RuntimePlatform: {
            CpuArchitecture: "X86_64",
            OperatingSystemFamily: "LINUX",
          },
          ContainerDefinitions: [
            {
              Name: "agent",
              Image: d.imageVersion,
              Essential: true,
              StopTimeout: 120,
              ReadonlyRootFilesystem: true,
              User: "10001",
              Environment: Object.entries(env).map(([Name, Value]) => ({
                Name,
                Value,
              })),
              MountPoints: [
                {
                  SourceVolume: "runtime",
                  ContainerPath: "/app/.runtime",
                  ReadOnly: false,
                },
              ],
              HealthCheck: {
                Command: [
                  "CMD",
                  "python",
                  "-m",
                  "backend.cloud_worker",
                  "--health",
                ],
                Interval: 30,
                Timeout: 5,
                Retries: 3,
                StartPeriod: 60,
              },
              LogConfiguration: {
                LogDriver: "awslogs",
                Options: {
                  "awslogs-group": c.KRONO_AGENT_LOG_GROUP,
                  "awslogs-region": c.AWS_REGION,
                  "awslogs-stream-prefix": d.id,
                },
              },
            },
          ],
          Volumes: [{ Name: "runtime" }],
        },
      },
      Service: {
        Type: "AWS::ECS::Service",
        Properties: {
          Cluster: c.KRONO_CLUSTER_ARN,
          ServiceName: d.stackName,
          TaskDefinition: { Ref: "Task" },
          DesiredCount: 1,
          LaunchType: "FARGATE",
          PlatformVersion: "1.4.0",
          EnableECSManagedTags: true,
          PropagateTags: "SERVICE",
          DeploymentConfiguration: {
            MaximumPercent: 100,
            MinimumHealthyPercent: 0,
            DeploymentCircuitBreaker: { Enable: true, Rollback: true },
          },
          NetworkConfiguration: {
            AwsvpcConfiguration: {
              AssignPublicIp: "DISABLED",
              Subnets: c.KRONO_PRIVATE_SUBNETS.split(","),
              SecurityGroups: [c.KRONO_AGENT_SECURITY_GROUP],
            },
          },
          Tags: [
            { Key: "KronoTenant", Value: p.userId },
            { Key: "KronoAgent", Value: agent.id },
            { Key: "KronoDeployment", Value: d.id },
            { Key: "KronoExpiresAt", Value: String(d.expiresAt) },
          ],
        },
      },
    },
    Outputs: {
      ServiceArn: { Value: { Ref: "Service" } },
      TaskDefinitionArn: { Value: { Ref: "Task" } },
    },
  };
}
